package org.apache.commons.lang;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_54_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        try {
            // This input is invalid because it uses a hyphen instead of an underscore
            LocaleUtils.toLocale("en-GB");
            fail("Expected IllegalArgumentException for invalid locale format");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-GB", e.getMessage());
        }
    }
}

